import{S as a,o as d,c,a9 as s,B as n}from"./chunks/framework.DxG24V0C.js";const l=JSON.parse('{"title":"压缩 / 上下文注入 / 子代理：装配式的长会话扩展","description":"","frontmatter":{"title":"压缩 / 上下文注入 / 子代理：装配式的长会话扩展"},"headers":[],"relativePath":"deepseek/07-compaction-context-subagent.md","filePath":"deepseek/07-compaction-context-subagent.md","lastUpdated":1787409644000}'),r={name:"deepseek/07-compaction-context-subagent.md"},h=Object.assign(r,{setup(i){const o=[{question:"压缩（compaction）在 session 的模型历史上到底做了什么？",options:["把一段旧表面折叠成一个摘要节点","把全部内容从头删光","把消息顺序重新排一遍","用摘要把旧段逐条抹平"],correct:0,explanation:"压缩 = 用 surface `{op: replace}` 把 [start,end] 旧段折叠成一个摘要 user/message。其余三项（清空/重排/逐条抹平）都不符合一次 replace 的语义。"},{question:"为什么把压缩做成一个可换的缝（Service Definition + Provider）？",options:["不同产品的压策略差异大，做成缝便于可换","这样强制所有产品共用同一个后端","做成函数比缝省一层抽象","不换 provider 就无法触发压缩"],correct:0,explanation:"压缩是个 seam（Definition=ctx.compaction、Provider=basic 等、Consumer=/compact）。不同产品的压缩策略差异大，做成可换缝后换 provider 即可，loop 无需改。"},{question:"压缩事务的锁是怎么释放的？",options:["start 先落、end 后落，方便检测孤儿锁","end 先落、start 后落","锁不进日志，由内存变量单管","每次压缩都新建一个新锁"],correct:0,explanation:'锁属于事件：`compaction/start` 先、`compaction/end` 最后。崩溃留下的"有 start 无 end"在日志里可检测，无需另设状态机。'},{question:"`agent.inject()` 与 `agent.followup()` 的关键区别是？",options:["inject 排队上下文而不唤醒，followup 唤醒","两者都唤醒但程度不同","inject 直接改摘要，followup 改日志","两者都只清空 inbox"],correct:0,explanation:'inject = next-step 且 wakeup=false（补充信息、不打断），followup = next-turn 且唤醒=true（要求干活）。这是"补充背景" vs "触发响应"的区分。'},{question:"子代理缝和 bash 缝最大的不同是？",options:["subagent 允许多个 provider 并存","bash 允许多个并发执行器","subagent 不能跨产品委托","subagent 不承载任何能力"],correct:0,explanation:"子代理是 `ctx.subagents`——named provider 注册表，spawn/fork/acp/codex/claude-code 多者共存；而 bash 只允许一个 executor。"}];return(p,e)=>{const t=a("Quiz");return d(),c("div",null,[e[0]||(e[0]=s(`<h1 id="压缩-上下文注入-子代理-装配式的长会话扩展" tabindex="-1">压缩 / 上下文注入 / 子代理：装配式的长会话扩展 <a class="header-anchor" href="#压缩-上下文注入-子代理-装配式的长会话扩展" aria-label="Permalink to &quot;压缩 / 上下文注入 / 子代理：装配式的长会话扩展&quot;">​</a></h1><blockquote><p>本文基于 <code>dsh-v0.1.0-rc.7</code>。项目处于 developer preview，迭代很快，文中机制以该基线为准。</p></blockquote><p>前面六篇我们把 <code>dsh</code> 从插件森林、Cordis、agent-loop、会话日志、工具管线一路看到 capability 缝。第七篇把三件&quot;装配另一层&quot;的事放在一起讲，因为它们共享同一个根基——<strong>capability 缝 + 会话日志</strong>：</p><ol><li><strong>压缩（compaction）</strong>：长会话超了上下文怎么办？——把&quot;压缩&quot;做成一个可换的缝。</li><li><strong>上下文注入（request context）</strong>：怎么在模型开口之外给它塞进&quot;该知道但没问&quot;的上下文？——<code>agent.inject()</code> + request-context 插件。</li><li><strong>子代理（subagent）</strong>：怎么让一个 agent 把活交给一个 child agent、甚至交给另一个产品里的 agent？——provider registry + 从主会话 fork。</li></ol><p>这三者放在一篇文章里，是因为它们<strong>都不是 agent-loop 脊柱的一部分，而是像 bash 一样&quot;可选的扩展&quot;</strong>——通过缝、注入、provider 这些第 6 篇的老朋友，松松地挂在 session log 周围。</p><p>先放这一篇的核心判断：</p><blockquote><p><strong>在 <code>dsh</code> 里，压缩、上下文注入、子代理都不是&quot;内建于主循环&quot;的魔法，而是三个独立扩展点：压缩是可换的缝（CompactionEngine），注入是 <code>agent.inject()</code> 排队，子代理是可换的 provider 注册表。</strong> 它们的共同根基是：一切演变都写在 session log 上、一切实现都可换 Provider。</p></blockquote><h2 id="一、压缩-把-长会话活下来-做成一个可换的缝" tabindex="-1">一、压缩：把&quot;长会话活下来&quot;做成一个可换的缝 <a class="header-anchor" href="#一、压缩-把-长会话活下来-做成一个可换的缝" aria-label="Permalink to &quot;一、压缩：把&quot;长会话活下来&quot;做成一个可换的缝&quot;">​</a></h2><h3 id="为什么压缩必须是一个缝" tabindex="-1">为什么压缩必须是一个缝 <a class="header-anchor" href="#为什么压缩必须是一个缝" aria-label="Permalink to &quot;为什么压缩必须是一个缝&quot;">​</a></h3><p>先看 <code>dsh-compaction-basic</code> 是 Service Provider 的角色，<code>docs/subsystems/compaction.md</code> 开头就说：</p><blockquote><p>The compaction seam — a capability seam split like <strong>bash</strong>: Service Definition (<code>ctx.compaction</code>), Service Provider (a backend such as dsh-compaction-basic), and human Consumer (dsh-command-compact). Compaction is <strong>one optional capability</strong>, not part of the agent-loop spine.</p></blockquote><p>所以**&quot;压缩&quot;与 bash 是完全同构的一个缝**：接口（<code>ctx.compaction</code>）+ Provider（basic 实现）+ 人为消费（<code>/compact</code> 命令）。这也回答了&quot;为什么把压缩做成缝&quot;：<strong>因为不同产品对&quot;怎么压&quot;的策略差异极大</strong>——有人要 token 预算、有人要模板摘要、有人接远程 summarizer。与其在 loop 里写死，不如像 bash 一样做成可换的缝：默认给 basic，需要别的就换 Provider。</p><h3 id="语义-把一段表面折叠成一个摘要" tabindex="-1">语义：把一段表面折叠成一个摘要 <a class="header-anchor" href="#语义-把一段表面折叠成一个摘要" aria-label="Permalink to &quot;语义：把一段表面折叠成一个摘要&quot;">​</a></h3><p>压缩在 session 模型里到底做了什么？答案是<strong>用一个新的 <code>user/message</code>（摘要）去&quot;替换&quot;一段旧 surface</strong>——这正是第 4 篇 <code>SurfaceOp</code> 里那个 <code>{ op: &#39;replace&#39;, start, end }</code> 的具体用量。<code>docs/subsystems/compaction.md</code> 把它说得很清楚：</p><blockquote><p>the summary itself rides on a separate <code>user/message</code> with <code>surfaceOp: { op: &#39;replace&#39;, start, end }</code> — the only surface mutation performed by summary compaction.</p></blockquote><p>也即：压缩 = 把 <code>[start, end]</code> 这段旧的模型历史，整个折叠成一个摘要节点。<code>start</code>/<code>end</code> 是 surface <strong>位置</strong>（不是数值区间），所以经过一次 replace 之后，新摘要节点落在旧位置，<code>start</code> 甚至可以大于 <code>end</code> —— 权威的被遮蔽节点集合是 <code>shadowedSeqs</code>。</p><h3 id="触发与策略" tabindex="-1">触发与策略 <a class="header-anchor" href="#触发与策略" aria-label="Permalink to &quot;触发与策略&quot;">​</a></h3><p><code>ctx.compaction</code> 的三个入口对应了三种时机：</p><ul><li><code>compactIfNeeded(agent, trigger, signal)</code>：<strong>自动</strong>策略，按 <code>trigger</code>（<code>pressure</code> 上下文压力 / <code>context-overflow</code> 容量溢出）；</li><li><code>compactNow(agent, signal, sourceCommandId?)</code>：<strong>手动</strong> <code>/compact</code>，在 idle 期做一次&quot;低于阈值也有用&quot;的压缩；</li><li><code>compactRegion(start, end, agent, signal?)</code>：显式压缩一段指定范围。</li></ul><p>自动压缩跑在<strong>串行的 <code>agent/pre-step</code></strong> 里（在推导请求之前检查压力），或进入 <code>agent/request-error</code> 做溢出恢复。<code>BasicCompactionEngine</code> 负责把 <code>ctx.tokenMeter</code> 压力量、token 预算保留下来、并用一次 <code>ctx.llm.stream()</code> 做摘要——关键设计是&quot;重放对话前缀以复用 provider 的 KV cache&quot;，而不是给模型发一个&quot;全新&quot;的上下文。</p><h3 id="compaction-事件-锁-结果都落日志" tabindex="-1">compaction/* 事件：锁 + 结果都落日志 <a class="header-anchor" href="#compaction-事件-锁-结果都落日志" aria-label="Permalink to &quot;compaction/* 事件：锁 + 结果都落日志&quot;">​</a></h3><p>压缩也有自己的会话事件：<code>compaction/start</code>（拿锁）→ 摘要 → <code>compaction/summary</code>（记录摘要、shadowed range、token 数、模型调用）→ <code>compaction/end</code>（释放）。<code>docs/subsystems/compaction.md</code> 强调<strong>锁是 <code>compaction/start</code> 先落、<code>end</code> 最后释放</strong>：</p><blockquote><p>The lock brackets the <strong>whole</strong> operation: <code>compaction/start</code> is appended first … then <code>compaction/end</code>. Releasing the lock last turns a crash mid-operation into a detectable orphaned lock (a start with no matching end).</p></blockquote><p>把锁放在日志里，就能复用第 4 篇&quot;events是事实&quot;的机制：崩溃造成的孤儿锁（有 start 无 end）可以从日志看出来，而不用额外一套状态机。</p><h2 id="二、上下文注入-模型-该知道的事-从哪排队进" tabindex="-1">二、上下文注入：模型&quot;该知道的事&quot;从哪排队进 <a class="header-anchor" href="#二、上下文注入-模型-该知道的事-从哪排队进" aria-label="Permalink to &quot;二、上下文注入：模型&quot;该知道的事&quot;从哪排队进&quot;">​</a></h2><p>&quot;长会话&quot;还有一个姊妹问题：除了用户已经说的，agent 需要<strong>主动往模型那边塞</strong>一些东西——文件变更提醒、子目录指令、cron 通知……这些在 <code>dsh</code> 里都属于&quot;request-context&quot;。</p><h3 id="agent-inject-排队但先不唤醒" tabindex="-1"><code>agent.inject()</code>：排队但先不唤醒 <a class="header-anchor" href="#agent-inject-排队但先不唤醒" aria-label="Permalink to &quot;\`agent.inject()\`：排队但先不唤醒&quot;">​</a></h3><p>第 3 篇讲 inbox 时已经见过 <code>agent.inject()</code> 的关键语义——它给 inbox 排队一条 <strong><code>next-step</code>、<code>wakeup=false</code></strong> 的消息：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// packages/core/agent-loop/src/agent.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input: UserMessage): </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;next-step&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 排队上下文，不唤醒</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这对应 <code>docs/subsystems/agent</code> 文档里的：</p><blockquote><p>inject — queue non-waking next-step context. A running driver claims it at the nearest later pre-step boundary; an idle driver leaves it pending until <code>followup()</code> or <code>steer()</code> wakes the driver.</p></blockquote><p><strong>精髓</strong>：注入的上下文<strong>不会自己打断 loop</strong>。一个 idle 的 agent 收到 <code>agent.inject()</code> 只是把它放 inbox 里排队，等某个 <code>followup()</code> 或 <code>steer()</code> 真正把它唤醒时才被认领。这样&quot;给 model 塞背景&quot;和&quot;让 model 必须回话&quot;被严格分开——被注入的内容在被唤醒的那个 step 里自然出现在 pre-step 的 batch 中。</p><h3 id="谁负责注入-context-包族" tabindex="-1">谁负责注入：context 包族 <a class="header-anchor" href="#谁负责注入-context-包族" aria-label="Permalink to &quot;谁负责注入：context 包族&quot;">​</a></h3><p><code>packages/context/README.md</code> 开头就说，&quot;context&quot; 组是 <strong>&quot;Product plugins that add model-visible request context without defining a tool&quot;</strong>——即一系列<strong>加模型可见上下文、但不定工具</strong>的插件：</p><table tabindex="0"><thead><tr><th>包</th><th>注入什么</th></tr></thead><tbody><tr><td><code>agent-instructions/</code></td><td>工作区指令（类似 dojo 的那个 AGENTS.md 内容），随创建按 agent/session 隔离</td></tr><tr><td><code>time-context/</code></td><td>当前时间 / 经过时长</td></tr><tr><td><code>tmux-context/</code></td><td>tmux 位置上下文</td></tr><tr><td><code>session-reference/</code></td><td>其他会话的有界快照</td></tr></tbody></table><p>这些插件是&quot;上下文注入&quot;的标准形态：它们不在模型面前定义一个工具，而是又在 <code>agent.inject()</code> / request 前把该说的东西排队进 inbox（<code>agent-instructions</code> 是默认 bundle 的一部分、可关闭；其余 opt-in）。</p><p>对比记忆（来自 OpenCode/Codex 那三栏）：OpenCode 有&quot;指令文件 + Skill 系统&quot;、Codex 有&quot;上下文注入&quot;，而 <code>dsh</code> 通过 <code>agent.inject()</code> + context 包族把&quot;塞谁、塞什么、塞多少&quot;也做成插件化装配。</p><h2 id="三、子代理-从-子-agent-到-跨产品委托" tabindex="-1">三、子代理：从&quot;子 agent&quot;到&quot;跨产品委托&quot; <a class="header-anchor" href="#三、子代理-从-子-agent-到-跨产品委托" aria-label="Permalink to &quot;三、子代理：从&quot;子 agent&quot;到&quot;跨产品委托&quot;&quot;">​</a></h2><h3 id="一个-provider-的注册表-而不是-一个子过程" tabindex="-1">一个 provider 的注册表，而不是&quot;一个子过程&quot; <a class="header-anchor" href="#一个-provider-的注册表-而不是-一个子过程" aria-label="Permalink to &quot;一个 provider 的注册表，而不是&quot;一个子过程&quot;&quot;">​</a></h3><p>子代理（subagent）是第七篇最值得展开的一点，因为它和 bash 有个关键不同——<strong>多个 Provider 同时存在</strong>。<code>docs/subsystems/subagent.md</code> 开篇点破：</p><blockquote><p>Like bash, it is one optional capability …, not part of the agent loop. It differs ... because <strong>multiple provider implementations coexist</strong> in one context, registered by name (<code>ctx.subagents</code>), while bash allows only one executor.</p></blockquote><p>bash 那类只允许一个执行器；子代理则是一个 <strong>named provider 注册表</strong>（<code>ctx.subagents</code>）——可以同时注册若干个 <code>spawn</code>、<code>fork</code>、<code>acp</code>、<code>codex</code>、<code>claude-code</code>……每个 provider 是一种&quot;child transport&quot;。这就是 <code>dsh</code> 里&quot;从 fresh child 到跨产品委托&quot;都能用一个接口实现的根因。</p><h3 id="一次-start-one-shot-委托" tabindex="-1">一次 start：one-shot 委托 <a class="header-anchor" href="#一次-start-one-shot-委托" aria-label="Permalink to &quot;一次 start：one-shot 委托&quot;">​</a></h3><p><code>ctx.subagents.start(name, request)</code> 选择某个 provider，起一个一次性 child：</p><ul><li><code>request</code> 带 <code>prompt</code>、<code>parent</code>（父 agent）、<code>signal</code>、以及可选 <code>outputSchema</code>/<code>maxDepth</code>/<code>toolFilter</code>/<code>persona</code>；</li><li>每个可选能力都要求 provider 声明的 <code>capabilities</code> 里 <code>true</code>，否则 <strong>fail loud</strong>（<code>UNSUPPORTED_CAPABILITY</code>）拒绝，而不是接受后忽略；</li><li>子代理<strong>通过 parent 的所有权/scope</strong>，用一个 <code>SubagentRun</code>（<code>result</code> + <code>dispose</code>）承载整个一次新 run。</li></ul><h3 id="从主会话-fork-到提交" tabindex="-1">从主会话 fork 到提交 <a class="header-anchor" href="#从主会话-fork-到提交" aria-label="Permalink to &quot;从主会话 fork 到提交&quot;">​</a></h3><p>&quot;子代理&quot;还有一种很优雅的来源：<strong>从主 agent 的会话 fork 出来</strong>。<code>docs/subsystems/subagent.md</code> 的&quot;Fork seeding&quot;一节：</p><blockquote><p>The fork backend passes a balanced completed-turn prefix of the parent&#39;s log — the parent&#39;s events up to and including its last <code>turn/end</code> — so the seed is contiguous-from-0 and the invariants replay accepts it.</p></blockquote><p>也就是 <code>fork</code> 这个 provider 拿<strong>父会话一段&quot;平衡的已完成回合前缀&quot;</strong>（到最后一个 <code>turn/end</code> 为止），把它作为 <code>seed</code> 给子代理创建一个新会话——本质上就是<strong>在会话日志上做了一个子会话分支</strong>，非常符合第 4 篇&quot;fork 就是拷贝日志前缀&quot;的思想。</p><h3 id="给模型委托、给产品委托" tabindex="-1">给模型委托、给产品委托 <a class="header-anchor" href="#给模型委托、给产品委托" aria-label="Permalink to &quot;给模型委托、给产品委托&quot;">​</a></h3><p>一个 subagent 的 provider 不止&quot;spawn/fork 两个本地后端&quot;：<code>ctx.subagents</code> 允许你把一个 child <strong>委托给另一个产品里的 agent</strong>——<code>subagent-acp</code>（ACP 协议）、<code>subagent-codex</code>、<code>subagent-claude-code</code> 这些 provider 直接通过 wire protocol 把委托发给 Codex 或 Claude Code。所以&quot;子代理&quot;的 provider 会连在一个私行的进程中，或直接跨产品，全看你怎么注册。</p><p><code>tool-subagent</code> 是 model-facing 的 Consumer：把&quot;请一个子代理做事&quot;这个东西暴露给模型，让模型决定什么时候 delegate、委托给谁。</p><h3 id="小结-子代理" tabindex="-1">小结（子代理） <a class="header-anchor" href="#小结-子代理" aria-label="Permalink to &quot;小结（子代理）&quot;">​</a></h3><p>子代理在 <code>dsh</code> 就是一个 provider 注册表（<code>ctx.subagents</code>），由单个 Consumer 定义了对外暴露；一次委托可以从&quot;同进程的新 agent（spawn/fork）&quot;到&quot;跨产品的协议搬运（acp/codex/claude-code）&quot;，都只是一次 <code>start()</code>，接口一样，Provider 换。</p><h2 id="四、三件事共享的内核-都是-session-上的扩展" tabindex="-1">四、三件事共享的内核：都是&quot;session 上的扩展&quot; <a class="header-anchor" href="#四、三件事共享的内核-都是-session-上的扩展" aria-label="Permalink to &quot;四、三件事共享的内核：都是&quot;session 上的扩展&quot;&quot;">​</a></h2><p>把第七篇三个主题并起来看，它们其实是&quot;同一根骨头的三种&quot;：</p><table tabindex="0"><thead><tr><th>扩展</th><th>落在 session 上做什么</th><th>换成 Provider 吗</th></tr></thead><tbody><tr><td>压缩</td><td>用 <code>compaction/*</code> 事件 + surface <code>replace</code> 折叠旧段成摘要</td><td>✅ <code>dsh-compaction</code> → <code>dsh-compaction-basic</code> / 别的前端</td></tr><tr><td>上下文注入</td><td><code>agent.inject()</code> / <code>agent.followup()</code> 往 inbox 排队；request-context 插件构建一段加入</td><td>插件（agent-instructions/time-context/...）可开关可增</td></tr><tr><td>子代理</td><td><code>subagent/start</code>/<code>subagent/end</code> 事件 + 从 parent fork 的 child session</td><td>✅ 一个 named provider 注册表，可有多 provider 共存</td></tr></tbody></table><p>关键线索：三件事都<strong>复用了我们在会话日志（第 4 篇）里建立的&quot;一切写进 session / surface&quot;的观念</strong>：</p><ul><li>压缩 fold 成 surface 节点，token 数、shadowed seqs、锁等都记录在 <code>compaction/*</code> 事件；</li><li>注入经 inbox 排队，最终成为 <code>user/message</code> &gt; 会话历史上的一条；</li><li>子代理的结果都以 <code>subagent/*</code> 事件记在日志里，child 就是 fork 出来的 another Session。</li></ul><p>这就是 <code>dsh</code> 的&quot;装配式扩展&quot;逻辑——<strong>外出的扩展都回写到 session 日志、都做成缝/provider</strong>，让&quot;长会话怎么活&quot;成为一个可配置的装配问题，而不是写死的一个算法。</p><h2 id="五、与三栏对比-把-长会话扩展-做成缝" tabindex="-1">五、与三栏对比：把&quot;长会话扩展&quot;做成缝 <a class="header-anchor" href="#五、与三栏对比-把-长会话扩展-做成缝" aria-label="Permalink to &quot;五、与三栏对比：把&quot;长会话扩展&quot;做成缝&quot;">​</a></h2><p>对比三栏（同能不同构）：</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode</th><th>Codex</th><th>Claude Code</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>压缩</td><td>2 级（Prune+Compact）</td><td>3 种</td><td>5 级</td><td><strong>做成可换缝</strong>（<code>ctx.compaction</code> + 可换 provider）</td></tr><tr><td>上下文注入</td><td>指令+Skill（5 层）</td><td>context diffing</td><td>claude.md+sessionMemory</td><td><strong><code>agent.inject()</code> 排队 + request-context 插件族</strong></td></tr><tr><td>子代理</td><td>SubAgent 广播</td><td>多 Agent</td><td>AgentTool</td><td><strong><code>ctx.subagents</code> provider 注册表（spawn/fork/acp/codex/claude-code）</strong></td></tr></tbody></table><p>核心差异一句话：</p><blockquote><p>三栏把压缩 / 上下文 / 子代理当作&quot;产品自己的&quot;机制各写各的（压缩有 2/3/5 种策略、上下文有 5 层）；<code>dsh</code> 把这三件都<strong>统一成&quot;可换的缝 / provider&quot;</strong>，让&quot;长会话怎么活&quot;变成装那个产品时&quot;换谁做、怎么配&quot;，而非&quot;改核心算法&quot;。</p></blockquote><p>这跟第六篇的 capability 缝的哲学一脉相承，也是 <code>dsh</code> 作为&quot;通用引擎&quot;最后一以贯之的表现——<strong>从模型适配、到上下文、到压缩、到子代理，全部是可缝/可配的轮子，而引擎骨架只有&quot;缝一致性 + 会话日志&quot;两根柱子。</strong></p><h2 id="结语-下一篇" tabindex="-1">结语 / 下一篇 <a class="header-anchor" href="#结语-下一篇" aria-label="Permalink to &quot;结语 / 下一篇&quot;">​</a></h2><p>第七篇把三件&quot;长会话怎么活下来&quot;的话题拆开了：压缩是可换缝、注入是 <code>agent.inject()</code> 排队、子代理是可换 provider 注册表。它们无一不是&quot;会话日志上的扩展&quot;。</p><p>但 <code>dsh</code> 的野心还没完——最&quot;魔法&quot;的一层我们留到最后一篇：<strong>agent 能不能改自己？</strong> 它能不能检查自己当前 mount 了哪些插件、主动 mount/unmount 新的插件、再配合主流 CLI（Claude Code / Codex）的 hook 协议握手？那就是全专栏最后一篇：<strong>08 自改 / hooks 桥 / 生态</strong>。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>`,70)),n(t,{questions:o})])}}});export{l as __pageData,h as default};
